(function(E){ const x = E["hr-m2"] = E["hr-m2"] || {units:{}}; x.units["hr-2-3"] = {"explain":{"id":"c-hr-2-3-e","course":"hr","unit":"hr-2-3","type":"explain","level":"B1","title":{"en":"Screening calls","tr":"Ön eleme görüşmeleri","fa":"مصاحبه‌ی تلفنی اولیه"},"objective":{"en":"After this lesson, you can run a short phone screen with polite indirect questions, and take notes.","tr":"Bu dersin sonunda kibar dolaylı sorularla kısa bir telefon ön elemesi yapıp not alabileceksin.","fa":"بعد از این درس می‌توانی با سؤال‌های غیرمستقیم و مؤدبانه یک غربالگری تلفنی کوتاه انجام بدهی و یادداشت برداری."},"hook":{"en":"Ask everyone the same short questions and note the facts. That shows quickly who to interview. 'Could you tell me when you can start?' Polite, clear, and the word order is not what you expect.","tr":"Herkese aynı kısa soruları sor ve olguları not al. Bu, kiminle mülakat yapacağını hızla gösterir. 'Could you tell me when you can start?' Kibar ve net; ama kelime sırası beklediğin gibi değil.","fa":"از همه همان سؤال‌های کوتاه را بپرس و واقعیت‌ها را یادداشت کن. این کار زود نشان می‌دهد با چه کسی مصاحبه کنی. «⁨Could you tell me when you can start?⁩» مؤدبانه و روشن است، ولی ترتیب کلمه‌ها آن چیزی نیست که انتظار داری."},"before":{"en":"Write the facts you noted in a short screening call, then one line: move to interview or not, and why.","tr":"Kısa bir ön görüşmede not ettiğin bilgileri yaz, sonra tek satır: görüşmeye çağrılsın mı, neden?","fa":"نکته‌هایی را که در یک تماس غربالگری کوتاه یادداشت کردی بنویس و بعد در یک خط: به مصاحبه دعوت شود یا نه و چرا."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Same short questions, facts only","tr":"Aynı kısa sorular, yalnızca olgular","fa":"همان سؤال‌های کوتاه، فقط واقعیت‌ها"},"body":{"en":"Ask everyone the same short questions to compare them. Note and confirm the facts.","tr":"Karşılaştırabilmek için herkese aynı kısa soruları sor. Olguları not al ve teyit et.","fa":"از همه همان سؤال‌های کوتاه را بپرس تا بتوانی مقایسه‌شان کنی. واقعیت‌ها را یادداشت کن و تأیید بگیر."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Indirect questions for screening","tr":"Ön eleme için dolaylı sorular","fa":"سؤال‌های غیرمستقیم برای غربالگری"},"steps":[{"en":"After a polite opener, use statement order.","tr":"Kibar bir girişten sonra düz cümle sırası kullan.","fa":"بعد از شروع مؤدبانه، ترتیب جمله‌ی خبری را به کار ببر.","ex":"Could you tell me when you can start?"},{"en":"No do, does or did after the opener.","tr":"Giriş kalıbından sonra do, does ya da did yok.","fa":"بعد از عبارت شروع، do و does و did نمی‌آید.","ex":"Could you tell me where you live?"},{"en":"Yes/no questions: use if or whether.","tr":"Evet/hayır soruları: if ya da whether kullan.","fa":"سؤال‌های بله و نه: از if یا whether استفاده کن.","ex":"Could you tell me if you have a licence?"},{"en":"Confirm it back as a statement.","tr":"Cevabı düz cümleyle teyit et.","fa":"جواب را با یک جمله‌ی خبری تأیید کن.","ex":"So you're available from the first of April."}],"table":{"headers":{"en":["Direct","Indirect (screening)"],"tr":["Doğrudan","Dolaylı (ön eleme)"],"fa":["سؤال مستقیم","سؤال غیرمستقیم (در غربالگری)"]},"rows":[["When can you start?","Could you tell me when you can start?"],["Do you have a licence?","Could you tell me if you have a licence?"],["Why did you leave?","Could you tell me why you left?"],["Confirming","So you're available from March."]]},"tip":{"en":"Turkish and Persian questions keep statement order, so the English swap (when can you) is new, and learners then use it everywhere. After Could you tell me, English goes back to statement order.","tr":"İngilizcede doğrudan soru sırası (when can you) dolaylı soruda geri döner: Could you tell me when you can start? Türkçedeki 'Ne zaman başlayabileceğinizi söyler misiniz?' de aslında bir düz yapıdır.","fa":"در فارسی می‌گوییم «می‌شود بگویید کی می‌توانید شروع کنید؟» و ترتیب کلمه‌ها عوض نمی‌شود. در انگلیسی سؤال مستقیم جابه‌جا می‌شود (when can you)، ولی در سؤال غیرمستقیم دوباره به ترتیب خبری برمی‌گردد: «when you can start»."},"wrong":"Could you tell me when can you start?","right":"Could you tell me when you can start?"},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Could you tell me if...?","meaning":{"en":"Polite yes/no screening question.","tr":"Kibar evet/hayır sorusu.","fa":"سؤال بله/نه‌ی مؤدبانه در غربالگری."}},{"phrase":"So you're available from...","meaning":{"en":"Confirms a date as a statement.","tr":"Tarihi düz cümleyle teyit eder.","fa":"یک تاریخ را به شکل جمله‌ی خبری تأیید می‌کند."}},{"phrase":"Let me ask that differently.","meaning":{"en":"Repairs a question the candidate did not understand.","tr":"Anlaşılmayan soruyu onarır.","fa":"سؤالی را که متقاضی نفهمیده، به شکل دیگری می‌پرسد."}},{"phrase":"notice period","meaning":{"en":"Time you must work after you tell your employer you are leaving.","tr":"ihbar süresi.","fa":"مدت پیش‌آگهی استعفا (مدتی که بعد از اعلام استعفا هنوز باید کار کنی)"}},{"phrase":"right to work","meaning":{"en":"Legal permission to work in a country.","tr":"çalışma izni.","fa":"مجوز قانونی کار در یک کشور"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Don't ask about current pay","tr":"Mevcut maaşı sorma","fa":"حقوق فعلی را نپرس"},"body":{"en":"Asking about current salary is now banned in many places: around twenty US states, and the EU under the Pay Transparency Directive, which countries had to make law by June 2026 (many are late). The reason: it can repeat old pay gaps. Asking about expected salary and the pay range of the role is safer. Check the local rule before the call.","tr":"Mevcut maaşı sormak, eski maaş farklarını tekrarlayabileceği için birçok yerde yasaktır: ABD'nin yaklaşık yirmi eyaletinde ve ülkelerin Haziran 2026'ya kadar yasalaştırması gereken Ücret Şeffaflığı Direktifi’yle AB'de; ancak birçok ülke gecikti. Beklenen maaşı ve pozisyonun maaş aralığını sormak daha güvenlidir. Aramadan önce yerel kuralı kontrol et.","fa":"در خیلی از جاها پرسیدن حقوق فعلی متقاضی ممنوع است، چون باعث می‌شود نابرابری‌های قدیمی حقوق ادامه پیدا کند. حدود بیست ایالت آمریکا از این جمله‌اند، و همین‌طور اتحادیه‌ی اروپا، طبق دستورالعمل شفافیت حقوق که کشورها باید تا ژوئن ۲۰۲۶ وارد قانون خود می‌کردند (خیلی از کشورها هنوز عقب‌اند). بهتر است حقوق درخواستی را بپرسی و بازه‌ی حقوق این موقعیت را بگویی. پیش از تماس، قانون محلی را بررسی کن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از گپ تا واقعیت تأییدشده"},"text":"Facts: You need the notice period. The candidate says one month.","item":"So, tell me about yourself. You seem nice!","why":{"en":"Weak: a chat, no fact to compare. Strong: one fact, asked as for all, confirmed.","tr":"Zayıf: sohbet; karşılaştırılacak olgu yok. Güçlü: herkese sorulan tek olgu, teyitli.","fa":"نسخه‌ی اول فقط گپ است و واقعیتی برای مقایسه نمی‌دهد. نسخه‌ی دوم یک واقعیت را مثل بقیه می‌پرسد و تأییدش می‌کند."},"answer":"Could you tell me your notice period? So that's one month.","cut":["tell me about yourself","You seem nice!"],"cutHint":{"en":"Tap what gives you no fact to compare.","tr":"Karşılaştırabileceğin hiçbir bilgi vermeyen şeylere dokun.","fa":"روی چیزهایی بزن که هیچ اطلاعاتی برای مقایسه به تو نمی‌دهند."}},"quick":{"prompt":"In a screening call in an EU country, which question is safer?","options":["What salary are you expecting?","What is your current salary?","How much did you earn last year?"],"correct":0,"why":{"en":"What salary are you expecting? Asking about current or past pay is banned in many places, because it can repeat old pay gaps.","tr":"What salary are you expecting? Şu anki ya da geçmiş maaşı sormak birçok yerde yasak, çünkü eski maaş farklarını sürdürebilir.","fa":"⁨What salary are you expecting?⁩ درست است: پرسیدن حقوق فعلی یا قبلی در خیلی جاها ممنوع است، چون ممکن است شکاف‌های قدیمی حقوق را تکرار کند."},"point":4,"hint2":{"en":"Past pay can carry old pay gaps into a new job. Which question looks forward, not back?","tr":"Geçmiş maaş, eski maaş farklarını yeni bir işe taşıyabilir. Hangi soru geriye değil, ileriye bakıyor?","fa":"حقوق قبلی می‌تواند شکاف‌های قدیمی حقوق را به کار تازه بکشاند. کدام سؤال به آینده نگاه می‌کند، نه به گذشته؟"}},"remember":{"en":"Cover 'Could you tell me'. What is left should be a normal statement: 'you can start', 'you have'. Result of this lesson: you can run a fair phone screen and keep clear notes.","tr":"'Could you tell me' kısmını kapat. Geriye kalan normal bir düz cümle olmalı: 'you can start', 'you have'. Bu dersin sonucu: adil bir telefon görüşmesi yapabilir ve net notlar tutabilirsin.","fa":"«Could you tell me» را بپوشان. چیزی که می‌ماند باید یک جمله‌ی خبری عادی باشد: «you can start»، «you have». حالا می‌توانی مصاحبه‌ی تلفنی منصفانه‌ای انجام بدهی و یادداشت‌های روشن داشته باشی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Sensitive questions: whether, would you mind if I asked","tr":"Hassas sorular: whether, would you mind if I asked","fa":"سؤال‌های حساس: whether، would you mind if I asked"},"steps":[{"en":"I was wondering whether + statement.","tr":"I was wondering whether + düz cümle.","fa":"بعد از I was wondering whether جمله‌ی خبری می‌آید.","ex":"I was wondering whether you would be willing to relocate."},{"en":"Would you mind if I + past simple.","tr":"Would you mind if I’dan sonra geçmiş zaman (past simple) gelir.","fa":"بعد از Would you mind if I گذشته‌ی ساده می‌آید.","ex":"Would you mind if I asked about your salary expectations?"},{"en":"The past here means polite, not past time.","tr":"Buradaki geçmiş zaman kibarlık bildirir, geçmişi değil.","fa":"گذشته اینجا برای ادب است، نه برای زمان گذشته.","ex":"asked = softer than ask"}],"table":{"headers":{"en":["Frame","Example"],"tr":["Kalıp","Örnek"],"fa":["مقدمه","مثال"]},"rows":[["I was wondering whether...","I was wondering whether you would be willing to relocate."],["Would you mind if I asked...?","Would you mind if I asked about your salary expectations?"],["Answer meaning \"yes, ask\"","No, not at all. Go ahead."]]},"body":{"en":"B2 track: ask the salary and relocation questions with one of the two frames, then confirm the answer as a statement.","tr":"B2 yolu: maaş ve taşınma sorularını bu iki kalıptan biriyle sor, sonra cevabı düz cümleyle teyit et.","fa":"مسیر B2: سؤال‌های حقوق و جابه‌جایی را با یکی از این دو مقدمه بپرس و بعد جواب را با یک جمله‌ی خبری تأیید کن."}},"source":{"en":"Informed by the EU Pay Transparency Directive.","tr":"AB Ücret Şeffaflığı Direktifi’nden yararlanır.","fa":"با استفاده از دستورالعمل شفافیت حقوق اتحادیه‌ی اروپا."}},"grammar":{"id":"c-hr-2-3-g","level":"B1","course":"hr","unit":"hr-2-3","title":"Indirect questions for screening","titleTr":"Ön eleme için dolaylı sorular","exp":{"en":"On a screening call, indirect questions sound polite and professional: \"Could you tell me when you can start?\" The part after the opener goes back to statement order: no inversion and no do/does/did. So: \"when you can start\", not \"when can you start\" and not \"when do you can start\". For yes/no questions use if or whether: \"Could you tell me if you have a Class C licence?\" To confirm what you heard, repeat it as a statement: \"So you're available from the first of March.\" Take short notes on facts only: dates, numbers, yes/no.","tr":"Ön eleme görüşmesinde dolaylı sorular kibar ve profesyonel durur: \"Could you tell me when you can start?\" Kalıptan sonraki kısım düz cümle sırasına döner: ters sıra yok, do/does/did yok. Yani: \"when you can start\"; \"when can you start\" ya da \"when do you can start\" değil. Evet/hayır soruları için if veya whether kullan: \"Could you tell me if you have a Class C licence?\" Duyduğunu teyit etmek için düz cümle olarak tekrar et: \"So you're available from the first of March.\" Kısa notları sadece olgularla tut: tarih, sayı, evet/hayır.","fa":"در مصاحبه‌ی تلفنی اولیه، سؤال غیرمستقیم مؤدبانه‌تر و حرفه‌ای‌تر به نظر می‌رسد: «⁨Could you tell me when you can start?⁩» نکته‌ی اصلی این است: بعد از عبارت شروع (Could you tell me)، بقیه‌ی جمله به ترتیب جمله‌ی خبری برمی‌گردد؛ یعنی فعل کمکی جابه‌جا نمی‌شود و do/does/did هم نمی‌آید. پس «when you can start» درست است، نه «when can you start» و نه «when do you can start». برای سؤال‌هایی که جوابشان بله یا نه است، از if یا whether استفاده کن: «⁨Could you tell me if you have a Class C licence?⁩» برای اینکه مطمئن شوی درست شنیده‌ای، جواب را به شکل جمله‌ی خبری تکرار کن: «⁨So you're available from the first of March.⁩» یادداشت‌هایت کوتاه باشد و فقط واقعیت‌ها را بنویس: تاریخ، عدد، بله یا نه."},"formsTable":{"headers":{"en":["Direct","Indirect (screening)"],"tr":["Doğrudan","Dolaylı (ön eleme)"],"fa":["سؤال مستقیم","سؤال غیرمستقیم (در غربالگری)"]},"rows":[["When can you start?","Could you tell me when you can start?"],["Do you have a licence?","Could you tell me if you have a licence?"],["Why did you leave?","Could you tell me why you left?"],["Confirming","So you're available from March."]]},"wrong":"Could you tell me when can you start?","right":"Could you tell me when you can start?","blank":{"sentence":"Could you tell me ___ you can start?","word":"when","distractors":["when can","when do"]},"wrong2":"Could you tell me do you have a licence?","right2":"Could you tell me if you have a licence?","blank2":{"sentence":"Could you tell me ___ you have a Class C licence?","word":"if","distractors":["do","what"]},"expParts":{"tryFrom":"blank","hook":{"en":"'Could you tell me when you can start?' Polite, clear, and the word order is not what you expect.","tr":"'Could you tell me when you can start?' Kibar ve net; ama kelime sırası beklediğin gibi değil.","fa":"«⁨Could you tell me when you can start?⁩» مؤدبانه و روشن است، ولی ترتیب کلمه‌ها آن چیزی نیست که انتظار داری."},"tryWhy":{"en":"when: after 'Could you tell me' the rest is a statement, so it is 'when you can start', not 'when can you'.","tr":"when: 'Could you tell me'den sonrası düz cümledir; yani 'when you can start', 'when can you' değil.","fa":"جواب when است: بعد از Could you tell me بقیه‌ی جمله خبری است؛ پس when you can start، نه when can you."},"rule":[{"en":"Opener + question word + statement order.","tr":"Giriş kalıbı + soru kelimesi + düz cümle sırası.","fa":"بعد از عبارت شروع، کلمه‌ی پرسشی می‌آید و بعد ترتیب جمله‌ی خبری.","ex":"Could you tell me when you can start?"},{"en":"No do, does or did after the opener.","tr":"Giriş kalıbından sonra do, does ya da did yok.","fa":"بعد از عبارت شروع، do و does و did نمی‌آید.","ex":"Could you tell me where you live?"},{"en":"Yes/no questions: use if or whether.","tr":"Evet/hayır soruları: if ya da whether kullan.","fa":"سؤال‌های بله و نه: از if یا whether استفاده کن.","ex":"Could you tell me if you have a licence?"},{"en":"Confirm it back as a statement.","tr":"Cevabı düz cümleyle teyit et.","fa":"جواب را با یک جمله‌ی خبری تأیید کن.","ex":"So you're available from the first of April."}],"test":{"en":"Cover 'Could you tell me'. What is left should be a normal statement: 'you can start', 'you have'.","tr":"'Could you tell me' kısmını kapat. Geriye kalan normal bir düz cümle olmalı: 'you can start', 'you have'.","fa":"«Could you tell me» را بپوشان. چیزی که می‌ماند باید یک جمله‌ی خبری عادی باشد: «you can start»، «you have»."},"contrast":{"en":"Turkish and Persian questions keep statement order, so the English swap (when can you) is new, and learners then use it everywhere. After Could you tell me, English goes back to statement order.","tr":"İngilizcede doğrudan soru sırası (when can you) dolaylı soruda geri döner: Could you tell me when you can start? Türkçedeki 'Ne zaman başlayabileceğinizi söyler misiniz?' de aslında bir düz yapıdır.","fa":"در فارسی می‌گوییم «می‌شود بگویید کی می‌توانید شروع کنید؟» و ترتیب کلمه‌ها عوض نمی‌شود. در انگلیسی سؤال مستقیم جابه‌جا می‌شود (when can you)، ولی در سؤال غیرمستقیم دوباره به ترتیب خبری برمی‌گردد: «when you can start»."}},"errorWatch":[{"find":["tell me when can you","tell me when do you","tell me where do you","tell me how long do you","tell me why do you","tell me when are you"],"fix":{"en":"After 'Could you tell me', use statement order: 'Could you tell me when you can start?'","tr":"'Could you tell me'den sonra düz cümle sırası kullan: 'Could you tell me when you can start?'","fa":"بعد از «Could you tell me» ترتیب خبری بیاور: «⁨Could you tell me when you can start?⁩»"}},{"find":["tell me do you","tell me are you","tell me can you","tell me have you"],"fix":{"en":"For a yes/no question use if: 'Could you tell me if you have a licence?'","tr":"Evet/hayır sorusu için if kullan: 'Could you tell me if you have a licence?'","fa":"برای سؤال بله و نه از if استفاده کن: «⁨Could you tell me if you have a licence?⁩»"}}]},"b2":{"id":"c-hr-2-3-b2","level":"B2","track":"B2","course":"hr","unit":"hr-2-3","title":"Sensitive questions: whether, would you mind if I asked","titleTr":"Hassas sorular: whether, would you mind if I asked","exp":{"en":"Some screening questions are sensitive: salary, relocation, gaps in a CV. B2 speakers add a distancing frame before them. \"I was wondering whether you would be willing to relocate.\" uses whether (more formal than if) and keeps statement order. \"Would you mind if I asked about your salary expectations?\" uses the past form asked to sound softer: the past here is about politeness, not time. After \"Would you mind if I...\", use the past simple (\"asked\"), not will or -ing. If the answer to \"Would you mind...?\" is \"No, go ahead\", it means yes, you may ask.","tr":"Bazı ön eleme soruları hassastır: maaş, taşınma, özgeçmişteki boşluklar. B2 seviyesinde konuşanlar bunlardan önce mesafe koyan bir kalıp ekler. \"I was wondering whether you would be willing to relocate.\" cümlesi whether (if'ten daha resmî) kullanır ve düz cümle sırasını korur. \"Would you mind if I asked about your salary expectations?\" daha yumuşak durmak için geçmiş biçim asked kullanır: buradaki geçmiş zaman zamanla değil, kibarlıkla ilgilidir. \"Would you mind if I...\" kalıbından sonra will ya da -ing değil, past simple (\"asked\") kullan. \"Would you mind...?\" sorusuna \"No, go ahead\" cevabı \"evet, sorabilirsin\" demektir.","fa":"بعضی سؤال‌های غربالگری حساس‌اند: حقوق، جابه‌جایی محل زندگی، فاصله‌های خالی در رزومه. در سطح ⁨B2⁩ قبل از این سؤال‌ها یک «مقدمه‌ی محترمانه» می‌گذارند تا سؤال کمتر مستقیم باشد. در «⁨I was wondering whether you would be willing to relocate.⁩» از ⁨whether⁩ استفاده شده که رسمی‌تر از ⁨if⁩ است، و ترتیب جمله‌ی خبری حفظ شده است. در «⁨Would you mind if I asked about your salary expectations?⁩» فعل ⁨asked⁩ گذشته است، اما ربطی به زمان ندارد؛ گذشته اینجا فقط لحن را مؤدبانه‌تر می‌کند. پس بعد از ⁨Would you mind if I⁩ گذشته‌ی ساده بیاور (⁨asked⁩)، نه ⁨will⁩ و نه ⁨-ing⁩. یک نکته‌ی مهم: اگر طرف در جواب «⁨Would you mind...?⁩» بگوید «⁨No, go ahead⁩»، یعنی «نه، اشکالی ندارد؛ بپرسید»."},"formsTable":{"headers":{"en":["Frame","Example"],"tr":["Kalıp","Örnek"],"fa":["مقدمه","مثال"]},"rows":[["I was wondering whether...","I was wondering whether you would be willing to relocate."],["Would you mind if I asked...?","Would you mind if I asked about your salary expectations?"],["Answer meaning \"yes, ask\"","No, not at all. Go ahead."]]},"wrong":"Would you mind if I will ask about your salary expectations?","right":"Would you mind if I asked about your salary expectations?","blank":{"sentence":"Would you mind if I ___ about your salary expectations?","word":"asked","distractors":["will ask","asking"]},"wrong2":"I was wondering would you be willing to relocate.","right2":"I was wondering whether you would be willing to relocate.","blank2":{"sentence":"I was wondering ___ you would be willing to relocate.","word":"whether","distractors":["that","what"]},"useIn":{"en":"B2 track: ask the salary and relocation questions with one of the two frames, then confirm the answer as a statement.","tr":"B2 yolu: maaş ve taşınma sorularını bu iki kalıptan biriyle sor, sonra cevabı düz cümleyle teyit et.","fa":"مسیر B2: سؤال‌های حقوق و جابه‌جایی را با یکی از این دو مقدمه بپرس و بعد جواب را با یک جمله‌ی خبری تأیید کن."},"exitItem":{"from":"hr-2-3","kind":"blank","prompt":"Would you mind if I ___ for a reference from your last employer?","options":["asked","will ask","asking"],"correct":0,"why":{"en":"asked: 'Would you mind if I' + past form makes a very polite request. 'Will ask' and 'asking' break the pattern.","tr":"asked: 'Would you mind if I' + geçmiş biçim çok kibar bir istek kurar. 'Will ask' ve 'asking' kalıbı bozar.","fa":"asked درست است، چون Would you mind if I با شکل گذشته درخواست خیلی مؤدبانه می‌سازد. will ask و asking الگو را خراب می‌کنند."},"hint2":{"en":"Would you mind if I... uses a polite past form, like If I were you. Which tense follows if here?","tr":"Would you mind if I... kibar bir geçmiş biçimi kullanır, If I were you gibi. Burada if’ten sonra hangi zaman gelir?","fa":"⁨Would you mind if I...⁩ یک شکل گذشته‌ی مؤدبانه دارد، مثل ⁨If I were you.⁩ این‌جا بعد از ⁨if⁩ چه زمانی می‌آید؟"}},"expParts":{"hook":{"en":"Salary and relocation are touchy. A short polite frame before the question makes it easy to answer.","tr":"Maaş ve taşınma hassas konular. Sorudan önce kısa, kibar bir giriş cevaplamayı kolaylaştırır.","fa":"حقوق و جابه‌جایی موضوع‌های حساسی‌اند. یک مقدمه‌ی کوتاه و مؤدبانه پیش از سؤال، جواب دادن را راحت می‌کند."},"tryWhy":{"en":"whether: it is more formal than if and keeps statement order after it.","tr":"whether: if'ten daha resmîdir ve ardından düz cümle sırası gelir.","fa":"جواب whether است: از if رسمی‌تر است و بعدش ترتیب خبری می‌آید."},"rule":[{"en":"I was wondering whether + statement.","tr":"I was wondering whether + düz cümle.","fa":"بعد از I was wondering whether جمله‌ی خبری می‌آید.","ex":"I was wondering whether you would be willing to relocate."},{"en":"Would you mind if I + past simple.","tr":"Would you mind if I’dan sonra geçmiş zaman (past simple) gelir.","fa":"بعد از Would you mind if I گذشته‌ی ساده می‌آید.","ex":"Would you mind if I asked about your salary expectations?"},{"en":"The past here means polite, not past time.","tr":"Buradaki geçmiş zaman kibarlık bildirir, geçmişi değil.","fa":"گذشته اینجا برای ادب است، نه برای زمان گذشته.","ex":"asked = softer than ask"}],"test":{"en":"They answer 'No, go ahead'? That means yes, you may ask.","tr":"'No, go ahead' diye mi cevap verdi? Bu 'evet, sorabilirsin' demek.","fa":"جواب داد «No, go ahead»؟ یعنی بله، می‌توانی بپرسی."},"contrast":{"en":"Turkish and Persian also soften with a past or conditional form ('sorabilir miydim', 'mishod bepursam'), so asked will feel familiar. The trap is the answer: 'No' to 'Would you mind' means 'go ahead'.","tr":"Türkçede de kibarlık için geçmiş biçim kullanılır: 'Maaş beklentinizi sorabilir miydim?'. Asıl tuzak cevaptadır: 'Would you mind...?' sorusuna 'No' demek 'buyurun, sorun' anlamına gelir.","fa":"در فارسی هم برای ادب گاهی از گذشته استفاده می‌کنیم: «می‌شد بپرسم...؟». تله‌ی اصلی در جواب است: «No» در جواب «Would you mind...?» یعنی «بفرمایید، بپرسید»."}},"errorWatch":[{"find":["mind if i will","mind if i asking","mind if i would ask"],"fix":{"en":"After 'Would you mind if I' use the past simple: 'Would you mind if I asked...?'","tr":"'Would you mind if I'dan sonra past simple kullan: 'Would you mind if I asked...?'","fa":"بعد از «Would you mind if I» گذشته‌ی ساده بیاور: «Would you mind if I asked...?»"}},{"find":["i was wondering would you","i was wondering are you","i was wondering do you","i was wondering can you"],"fix":{"en":"Use whether or if and statement order: 'I was wondering whether you would be willing to relocate.'","tr":"whether ya da if ve düz cümle sırası kullan: 'I was wondering whether you would be willing to relocate.'","fa":"از whether یا if و ترتیب خبری استفاده کن: «⁨I was wondering whether you would be willing to relocate.⁩»"}}]},"vocab":{"id":"c-hr-2-3-v","level":"B1","category":"vocab","course":"hr","unit":"hr-2-3","goals":["career"],"title":{"en":"Screening and Notes","tr":"Ön Eleme ve Notlar","fa":"غربالگری و یادداشت‌برداری"},"cards":[{"word":"screening call","sentence":"The screening call takes about ten minutes.","meaning":{"en":"A short first phone interview.","tr":"ön eleme görüşmesi.","fa":"مصاحبه‌ی تلفنی اولیه؛ تماس غربالگری"}},{"word":"notice period","sentence":"What is your notice period?","meaning":{"en":"Time you must work after you tell your employer you are leaving.","tr":"ihbar süresi.","fa":"مدت پیش‌آگهی استعفا (مدتی که بعد از اعلام استعفا هنوز باید کار کنی)"}},{"word":"available","sentence":"Are you available from the first of March?","meaning":{"en":"Free and able to start or meet.","tr":"müsait.","fa":"در دسترس؛ آماده‌ی شروع کار یا جلسه"}},{"word":"current salary","sentence":"In many places you must not ask about current salary; ask about expected salary instead.","meaning":{"en":"The pay someone has now.","tr":"mevcut maaş.","fa":"حقوق فعلی"}},{"word":"expected salary","sentence":"His expected salary is 8,000 dirhams.","meaning":{"en":"The pay someone hopes to get.","tr":"beklenen maaş.","fa":"حقوق درخواستی؛ حقوق مورد انتظار"}},{"word":"relocate","sentence":"Would you be willing to relocate to Dubai?","meaning":{"en":"To move to live in another place for work.","tr":"taşınmak (iş için).","fa":"جابه‌جا شدن محل زندگی به خاطر کار"}},{"word":"right to work","sentence":"Do you have the right to work in the UAE?","meaning":{"en":"Legal permission to work in a country.","tr":"çalışma izni.","fa":"مجوز قانونی کار در یک کشور"}},{"word":"go through","sentence":"Let's go through your CV together.","meaning":{"en":"To look at something carefully, point by point.","tr":"gözden geçirmek.","fa":"یکی‌یکی مرور کردن؛ با دقت بررسی کردن"}},{"word":"next steps","sentence":"I'll explain the next steps at the end.","meaning":{"en":"What will happen after this.","tr":"sonraki adımlar.","fa":"قدم‌های بعدی"}},{"word":"take notes","sentence":"I'll take notes while we talk, if that's okay.","meaning":{"en":"To write short points while listening.","tr":"not almak.","fa":"یادداشت برداشتن"}}]},"story":{"id":"c-hr-2-3-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-2-3","title":{"en":"Question Three","tr":"Üçüncü Soru","fa":"سؤال سوم"},"text":"Leyla had five questions on a card and ten minutes for each call. Deniz Aydin was the fourth call that morning.\n\n\"Thank you for your time, Deniz. I'll take some notes while we talk, is that okay?\"\n\n\"Of course.\"\n\n\"Could you tell me why you want to work in Dubai?\" He said his sister lived there and the roads were better. Fine.\n\n\"Could you tell me if you have a Class C licence?\" \"Yes, since 2016.\" Good.\n\nQuestion three was: \"What notice period do you have?\"\n\n\"Notice? Yes, yes. I get notice. From my boss, every month.\" He sounded sure.\n\nLeyla stopped. That was not an answer. \"Sorry, let me ask differently. Could you tell me how long you need to work before you can start with us?\"\n\n\"Ah!\" He laughed. \"Sorry. In my head 'notice' was a message. One month. I need to work one more month.\"\n\n\"So you're available from the first of April,\" Leyla said. \"Is that right?\"\n\n\"Yes. Correct.\"\n\nWhen the call ended she looked at her card. Question three had not been bad. But \"notice period\" was an HR phrase, and Deniz was a driver. She crossed it out and wrote a new line: Could you tell me how long you need before you can start?\n\nTwelve minutes of fast, careful questions, and her ears were warm. Somewhere in Istanbul, Deniz was probably telling his sister about the strange question about notice.","vocab":[{"word":"card","en":"Here: a small paper with your questions.","tr":"kart (not kartı)","fa":"کارت یادداشت (کاغذ کوچکی که سؤال‌ها رویش نوشته شده)"},{"word":"sure","en":"Certain; with no doubt.","tr":"emin","fa":"مطمئن"},{"word":"differently","en":"In another way.","tr":"farklı biçimde","fa":"به شکلی دیگر"},{"word":"cross out","en":"To draw a line through something you wrote.","tr":"üstünü çizmek","fa":"روی چیزی خط کشیدن؛ خط زدن"},{"word":"jargon","en":"Special words only people in one job know.","tr":"meslek jargonu","fa":"اصطلاحات تخصصی (که فقط اهل همان کار می‌فهمند)"}],"quiz":[{"prompt":"Why did Deniz answer question three strangely?","options":["He did not know the HR phrase \"notice period\"","He did not want the job","He could not hear her"],"correct":0},{"prompt":"Choose the correct question.","options":["Could you tell me when can you start?","Could you tell me when you can start?","Could you tell me when do you start?"],"correct":1},{"prompt":"What did Leyla do to confirm what she heard?","options":["Repeated it as a statement: \"So you're available from the first of April.\"","Asked the same question again","Ended the call"],"correct":0},{"prompt":"How might Deniz feel after the call?","options":["A little embarrassed, but also relaxed because she was kind","Very angry","Sure he lost the job"],"correct":0}],"notice":{"en":"One of Leyla's five questions does not work. Find it, and notice how she asks it again.","tr":"Leyla'nın beş sorusundan biri işe yaramıyor. Onu bul ve soruyu yeniden nasıl sorduğuna dikkat et.","fa":"یکی از پنج سؤال لیلا جواب نمی‌دهد. پیدایش کن و دقت کن چطور دوباره می‌پرسدش."},"bridge":{"en":"'Could you tell me how long you need...?' Next: see why the word order changes after the opener.","tr":"'Could you tell me how long you need...?' Sırada: giriş kalıbından sonra kelime sırasının neden değiştiğini gör.","fa":"«Could you tell me how long you need...?» قدم بعد: ببین چرا بعد از عبارت شروع، ترتیب کلمه‌ها عوض می‌شود."}},"speaking":{"id":"hr-2-3","course":"hr","unit":"hr-2-3","topic":{"en":"Running a 5-Question Screening Call","tr":"5 Soruluk Ön Eleme Görüşmesi Yapmak","fa":"مصاحبه‌ی تلفنی اولیه با پنج سؤال"},"warmup":{"en":"Which words in your job might a non-expert not understand? Name two.","tr":"İşindeki hangi sözcükleri uzman olmayan biri anlamayabilir? İki tane say.","fa":"کدام کلمه‌های شغل تو را ممکن است کسی که اهل این کار نیست نفهمد؟ دو تا را نام ببر."},"questions":[{"en":"Open the call, ask permission to take notes, and say how long it will take.","tr":"Görüşmeyi aç, not alma izni iste ve ne kadar süreceğini söyle.","fa":"تماس را شروع کن، برای یادداشت‌برداری اجازه بگیر و بگو گفتگو چقدر طول می‌کشد."},{"en":"Ask: why Dubai, licence, when they can start, right to work, expected salary. Use indirect questions.","tr":"Sor: neden Dubai, ehliyet, ne zaman başlayabilir, çalışma izni, beklenen maaş. Dolaylı sorular kullan.","fa":"این‌ها را بپرس: چرا دبی، نوع گواهینامه، از چه زمانی می‌تواند شروع کند، مجوز کار، حقوق درخواستی. از سؤال غیرمستقیم استفاده کن."},{"en":"Confirm each important answer in your own words, then explain the next steps.","tr":"Her önemli cevabı kendi sözlerinle teyit et, sonra sonraki adımları açıkla.","fa":"هر جواب مهم را با کلمات خودت تکرار و تأیید کن، بعد قدم‌های بعدی را توضیح بده."}],"followups":[{"en":"The candidate does not understand a phrase. Say it again in simpler words.","tr":"Aday bir ifadeyi anlamıyor. Daha basit sözcüklerle yeniden söyle.","fa":"متقاضی یکی از عبارت‌های تو را نمی‌فهمد. همان را با کلمات ساده‌تر دوباره بگو."},{"en":"Now ask three screening questions for a job at your own company.","tr":"Şimdi kendi şirketindeki bir iş için üç ön eleme sorusu sor.","fa":"حالا برای یک شغل در شرکت خودت سه سؤال غربالگری بپرس."}],"expressions":[{"phrase":"Could you tell me if...?","meaning":{"en":"Polite yes/no screening question.","tr":"Kibar evet/hayır sorusu.","fa":"سؤال بله/نه‌ی مؤدبانه در غربالگری."}},{"phrase":"So you're available from...","meaning":{"en":"Confirms a date as a statement.","tr":"Tarihi düz cümleyle teyit eder.","fa":"یک تاریخ را به شکل جمله‌ی خبری تأیید می‌کند."}},{"phrase":"Let me ask that differently.","meaning":{"en":"Repairs a question the candidate did not understand.","tr":"Anlaşılmayan soruyu onarır.","fa":"سؤالی را که متقاضی نفهمیده، به شکل دیگری می‌پرسد."}}],"culture":{"en":"Asking about current salary is now banned in many places: around twenty US states, and the EU under the Pay Transparency Directive, which countries had to make law by June 2026 (many are late). The reason: it can repeat old pay gaps. Asking about expected salary and the pay range of the role is safer. Check the local rule before the call.","tr":"Mevcut maaşı sormak, eski maaş farklarını tekrarlayabileceği için birçok yerde yasaktır: ABD'nin yaklaşık yirmi eyaletinde ve ülkelerin Haziran 2026'ya kadar yasalaştırması gereken Ücret Şeffaflığı Direktifi’yle AB'de; ancak birçok ülke gecikti. Beklenen maaşı ve pozisyonun maaş aralığını sormak daha güvenlidir. Aramadan önce yerel kuralı kontrol et.","fa":"در خیلی از جاها پرسیدن حقوق فعلی متقاضی ممنوع است، چون باعث می‌شود نابرابری‌های قدیمی حقوق ادامه پیدا کند. حدود بیست ایالت آمریکا از این جمله‌اند، و همین‌طور اتحادیه‌ی اروپا، طبق دستورالعمل شفافیت حقوق که کشورها باید تا ژوئن ۲۰۲۶ وارد قانون خود می‌کردند (خیلی از کشورها هنوز عقب‌اند). بهتر است حقوق درخواستی را بپرسی و بازه‌ی حقوق این موقعیت را بگویی. پیش از تماس، قانون محلی را بررسی کن."},"model":"Hi Deniz, it's Leyla from Atlas Logistics. Thanks for your time. This will take about ten minutes, and I'll take some notes, if that's okay. Could you tell me why you want to work in Dubai? And could you tell me if you have a Class C licence? Great. So you're available from the first of April. Is that right? The next step is an interview next week.","selfCheck":[{"en":"I asked permission to take notes and said how long the call takes.","tr":"Not almak için izin istedim ve görüşmenin ne kadar süreceğini söyledim.","fa":"برای یادداشت برداشتن اجازه گرفتم و گفتم تماس چقدر طول می‌کشد."},{"en":"My indirect questions kept statement order (when you can start).","tr":"Dolaylı sorularımda düz cümle sırasını korudum (when you can start).","fa":"در سؤال‌های غیرمستقیم ترتیب خبری را نگه داشتم (when you can start)."},{"en":"I confirmed one answer back as a statement (So you're...).","tr":"Bir cevabı düz cümleyle teyit ettim (So you're...).","fa":"یک جواب را با جمله‌ی خبری تأیید کردم (⁨So you're...⁩)."},{"en":"I explained the next step.","tr":"Sonraki adımı açıkladım.","fa":"قدم بعدی را توضیح دادم."}]},"writing":{"id":"c-hr-2-3-w","title":{"en":"Screening notes on Deniz","tr":"Deniz için ön eleme notları","fa":"یادداشت‌های مصاحبه‌ی اولیه با دنیز"},"course":"hr","unit":"hr-2-3","type":"writing","difficulty":"medium","prompt":{"en":"Fill in the screening notes for Deniz from the call (facts only, 4 lines), then write a one-line recommendation: move to interview or not, and why.","tr":"Görüşmeye dayanarak Deniz için ön eleme notlarını doldur (sadece olgular, 4 satır), sonra tek satırlık öneri yaz: mülakata geçsin mi, neden?","fa":"از روی تماس، فرم یادداشت غربالگری دنیز را پر کن (فقط واقعیت‌ها، در چهار خط). بعد در یک خط توصیه‌ات را بنویس: به مرحله‌ی مصاحبه برود یا نه و چرا."},"model":"Candidate: Deniz Aydin. Reason for Dubai: sister lives there. Licence: Class C since 2016. Available: from 1 April (one month's notice). Recommendation: move to interview, because he meets all essential requirements and answered clearly once the question was simplified.","frame":"Candidate: ___. Reason for Dubai: ___. Licence: ___. Available: ___. Recommendation: ___, because ___.","words":[{"word":"available"},{"word":"licence"},{"word":"recommendation"}],"minWords":35,"minSentences":3,"rubric":["Task done: 4 facts + recommendation with a reason","Organised: one label per fact","Language: statements with correct dates; because-clause","Tone: neutral, facts only, no opinions about the person"],"rubricI18n":{"tr":["Görev: 4 bilgi + gerekçeli öneri","Düzen: her bilgiye bir başlık","Dil: doğru tarihli düz cümleler; because ile yan cümle","Üslup: tarafsız, yalnızca bilgi; kişi hakkında yorum yok"],"fa":["کامل بودن کار: چهار واقعیت به‌همراه یک پیشنهاد با دلیل","نظم: برای هر واقعیت یک عنوان","زبان: جمله‌های خبری با تاریخ‌های درست؛ جمله‌ای با because","لحن: بی‌طرف و فقط واقعیت‌ها؛ بدون نظر شخصی درباره‌ی فرد"]},"portfolio":null,"parts":[{"t":{"en":"His reason for Dubai","tr":"Dubai’yi seçme nedeni","fa":"دلیلش برای دبی"},"find":["reason","because","lives there"],"sample":"his sister lives there"},{"t":{"en":"His licence","tr":"Ehliyeti","fa":"گواهینامه‌اش"},"find":["licence","license","class c"],"sample":"Class C since 2016"},{"t":{"en":"When he can start","tr":"Ne zaman başlayabileceği","fa":"از کی می‌تواند شروع کند"},"find":["available","notice","start"],"sample":"from 1 April, one month’s notice"},{"t":{"en":"Your recommendation with a reason","tr":"Gerekçeli önerin","fa":"پیشنهادت همراه با دلیل"},"find":["recommendation","recommend","move to interview"],"sample":"interview: he meets all the essentials"}]},"perspective":{"id":"c-hr-2-3-p","title":{"en":"Deniz after question three","tr":"Üçüncü sorudan sonra Deniz","fa":"دنیز بعد از سؤال سوم"},"course":"hr","unit":"hr-2-3","type":"perspective","minSentences":3,"prompt":{"en":"You are Deniz after question three. Write 2 sentences in first person: what did you hear and what did you say? Then rewrite Leyla's question so nobody could misread it (1 sentence).","tr":"Üçüncü sorudan sonraki Deniz'sin. Birinci tekil şahısla 2 cümle yaz: ne duydun ve ne söyledin? Sonra Leyla'nın sorusunu kimsenin yanlış anlamayacağı biçimde yeniden yaz (1 cümle).","fa":"تو دنیز هستی و سؤال سوم تازه تمام شده است. از زبان خودت دو جمله بنویس: چه شنیدی و چه جوابی دادی؟ بعد سؤال لیلا را طوری بازنویسی کن که هیچ‌کس نتواند اشتباه برداشت کند (یک جمله)."}},"exit":{"id":"c-hr-2-3-x","course":"hr","unit":"hr-2-3","type":"exit","items":[{"from":"hr-2-3","kind":"blank","prompt":"Could you tell me where ___?","options":["do you live","you live","you do live"],"correct":1,"point":2,"why":{"en":"you live: inside 'Could you tell me where...', use statement order and no do. 'Do you live' is question order, and 'you do live' adds do.","tr":"you live: 'Could you tell me where...' içinde düz sıra kullanılır ve do gelmez. 'Do you live' soru sırasıdır; 'you do live' do ekler.","fa":"you live درست است، چون بعد از Could you tell me where ترتیب خبری می‌آید و do لازم نیست. do you live ترتیب سؤالی است و you do live do اضافه دارد."}},{"from":"hr-2-3","kind":"blank","prompt":"Can I ask ___ you have worked nights before?","options":["whether","what","do"],"correct":0,"point":2,"why":{"en":"whether: it opens an indirect yes/no question. 'What' needs a missing thing, and 'do' can't follow ask here.","tr":"whether: dolaylı bir evet/hayır sorusu açar. 'What' eksik bir şey ister; 'do' burada ask'ten sonra gelmez.","fa":"whether درست است، چون سؤال بله‌یا‌نهِ غیرمستقیم را باز می‌کند. what دنبال چیزی است که جمله ندارد و do اینجا بعد از ask نمی‌آید."}},{"from":"hr-2-3","kind":"mcq","prompt":"Which sentence confirms a date?","options":["So you're available from the first of April.","When are you available?","Notice period?"],"correct":0,"point":3,"why":{"en":"'So you're available from the first of April' repeats the date back to confirm it. The other two only ask, and 'Notice period?' is too short to be polite.","tr":"'So you're available from the first of April' tarihi teyit etmek için tekrar eder. Diğer ikisi yalnızca sorar; 'Notice period?' kibar olamayacak kadar kısadır.","fa":"«So you're available from the first of April» تاریخ را برای تأیید تکرار می‌کند. دو گزینه‌ی دیگر فقط می‌پرسند و «Notice period?» برای مؤدب بودن زیادی کوتاه است."},"hint2":{"en":"To confirm, you say the detail back as a statement. Which sentence repeats a date you heard?","tr":"Teyit etmek için bilgiyi bir cümle olarak geri söylersin. Hangi cümle duyduğun bir tarihi tekrarlıyor?","fa":"برای تأیید، همان اطلاعات را به شکل یک جمله‌ی خبری برمی‌گردانی. کدام جمله تاریخی را که شنیدی تکرار می‌کند؟"}},{"from":"hr-2-2","kind":"blank","prompt":"We need people ___ stay calm with angry customers.","options":["who","what","whose"],"correct":0,"point":2,"why":{"en":"who: it refers to people. 'What' can't join a clause to 'people', and 'whose' shows ownership.","tr":"who: insanları anlatır. 'What' bir yan cümleyi 'people'a bağlayamaz; 'whose' sahiplik gösterir.","fa":"who درست است، چون به آدم‌ها برمی‌گردد. what نمی‌تواند جمله را به people وصل کند و whose مالکیت را نشان می‌دهد."},"hint2":{"en":"The gap joins people to what they do. Which word starts a clause about people?","tr":"Boşluk insanları yaptıkları şeye bağlıyor. İnsanlarla ilgili bir yan cümleyi hangi kelime başlatır?","fa":"جای خالی آدم‌ها را به کاری که می‌کنند وصل می‌کند. کدام کلمه جمله‌ای درباره‌ی آدم‌ها را شروع می‌کند؟"}},{"from":"hr-2-1","kind":"mcq","prompt":"Which is an ESSENTIAL requirement?","options":["Candidates must hold a Class C licence.","Arabic would be an advantage.","Experience is preferred."],"correct":0,"point":1,"why":{"en":"'Candidates must hold a Class C licence' is essential: must. 'Would be an advantage' and 'is preferred' are desirable.","tr":"'Candidates must hold a Class C licence' zorunludur: must. 'Would be an advantage' ve 'is preferred' istenen ama şart olmayan şeylerdir.","fa":"«Candidates must hold a Class C licence» ضروری است، چون must دارد. would be an advantage و is preferred یعنی بودنش خوب است."}},{"from":"hr-1-3","kind":"blank","prompt":"Sorry, did you ___ Tuesday or Thursday?","options":["say","said","says"],"correct":0,"point":2,"why":{"en":"say: after 'did you', the plain verb. 'Said' doubles the past, and 'says' is the present.","tr":"say: 'did you'dan sonra yalın fiil. 'Said' geçmişi iki kez söyler; 'says' şimdiki zamandır.","fa":"say درست است، چون بعد از did you فعل ساده می‌آید. said گذشته را دو بار می‌گوید و says زمان حال است."}},{"from":"hr-2-3","kind":"mcq","prompt":"You screen five candidates for one role. Why ask each of them the same short questions?","options":["So you can compare their answers fairly","So the calls are shorter","So you can skip the notes"],"correct":0,"why":{"en":"So you can compare them fairly: the same questions give the same kind of facts for each person. Then note and confirm the facts.","tr":"Onları adil biçimde karşılaştırabilmek için: Aynı sorular her kişi için aynı türden bilgiler verir. Sonra bilgileri not et ve teyit et.","fa":"برای اینکه بتوانی منصفانه مقایسه‌شان کنی: سؤال‌های یکسان برای هر نفر همان نوع اطلاعات را می‌دهد. بعد اطلاعات را یادداشت و تأیید کن."},"point":1}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
